        this.init = function () {
            const indexSelectionSelectbox = document.querySelector( m_profilingControllerOptions.indexSelectboxSelector );
            const promiseIfNeeded = indexSelectionSelectbox ? ControllerHelper.initAvailableIndicesSelectbox( m_elasticsearchModel, indexSelectionSelectbox ) : Promise.resolve();
            promiseIfNeeded
                .then( () => {
                    m_elasticsearchModel.getMappingOfIndex()
                        .then( _getFunctionToHandleElasticsearchMapping(me.doSearchWithCurrentUserSettings, false ) )
                        .catch( BaseUtils.standardErrorCatcher );

                }).catch( BaseUtils.standardErrorCatcher );

            // Important: return the this instance so we can use chaining calls. Example: In TestController.js
            return this;
        };
        // **********************************************************************************************************
        this.reset = function () {
            m_elasticsearchFilterManager.reset();  // mainly: remove installed event hamdlers
            HtmlModel.emptyElement( m_profilingControllerOptions.fieldChooserSelector );
            HtmlModel.emptyElement( "#filterDestination" );
            HtmlModel.emptyElement( "#filterExplanation" );
            HtmlModel.emptyElement( "#outputExplanation" );
            HtmlModel.getSpecifiedElement( "#outputControls .chartTypeChooser" ).remove();
            document.querySelectorAll( "#outputControls div" ).forEach( (x) => x.remove() );
        };
        // **********************************************************************************************************
        this.resetPredefined = function () {
            m_elasticsearchFilterManager.reset();  // mainly: remove installed event hamdlers
            HtmlModel.emptyElement( m_profilingControllerOptions.staticOutputTypeChooser );
            HtmlModel.emptyElement( "#queryList" );
        };
        // **********************************************************************************************************
        this.getGraphModelObject = function () {
            return m_graphModel;
        };

        // **********************************************************************************************************
        this.getElasticsearchModel = function() {
            return m_elasticsearchModel;
        };
